/* News index pagination: 12 posts a page, state in the hash, as the handoff
   specifies. The platform's blog index renders every post in one list, so the
   paging is applied over that live list rather than a typed one. Runs only on
   the index itself; every other page leaves this untouched. */
(function () {
  if (!/^\/news\/?$/.test(window.location.pathname)) return;
  var list = document.querySelector('.bz-container > ul.bz-bare');
  if (!list) return;
  var section = list.closest('.bz-block');
  if (section) section.classList.add('tc-news');

  var PER = 12;
  var items = Array.prototype.slice.call(list.children);
  if (items.length <= PER) return;
  var pages = Math.ceil(items.length / PER);

  var pager = document.createElement('nav');
  pager.className = 'tc-pager';
  pager.setAttribute('aria-label', 'Posts');
  list.parentNode.insertBefore(pager, list.nextSibling);

  function show(n) {
    n = Math.min(Math.max(1, n), pages);
    items.forEach(function (li, i) {
      li.hidden = Math.floor(i / PER) + 1 !== n;
    });
    pager.textContent = '';
    for (var i = 1; i <= pages; i++) {
      var a = document.createElement('a');
      a.href = '#page-' + i;
      a.textContent = String(i);
      if (i === n) a.setAttribute('aria-current', 'page');
      pager.appendChild(a);
    }
  }

  function fromHash() {
    var m = /^#page-(\d+)$/.exec(window.location.hash);
    show(m ? Number(m[1]) : 1);
  }
  window.addEventListener('hashchange', fromHash);
  fromHash();
})();
